// === 1. Объявление переменных и объектов ===
let appTitle = "AsanaliScript Control Panel"
let isSystemReady = true
let systemInfo = { status: "Active", port: 3000 }

// === 2. Консольный вывод (echo) ===
echo "Запуск приложения: $appTitle"
echo "Пользователь: $User | Оation System: $ARCH"

// === 3. Логика и условия (if / else) ===
if $isSystemReady == true {
    echo "Система готова! Статус: $systemInfo.status"
} else {
    echo "Ошибка инициализации системы!"
}

// === 4. Веб-маршрут (бэкенд API) ===
route GET "/api/status" {
    {"app": "$appTitle", "user": "$User", "status": "online"}
}

// === 5. Графический UI и верстка (window) ===
window(
    <style>
        body {
            background-color: #0f172a;
            color: #f8fafc;
            font-family: 'Segoe UI', sans-serif;
            padding: 30px;
        }
        .card {
            background: #1e293b;
            padding: 20px;
            border-radius: 10px;
            border: 1px solid #334155;
            max-width: 400px;
        }
        h1 { color: #38bdf8; margin-top: 0; }
        button {
            background: #0284c7;
            color: white;
            border: none;
            padding: 8px 16px;
            border-radius: 5px;
            cursor: pointer;
        }
        button:hover { background: #0369a1; }
    </style>

    <div class="card">
        <h1>$appTitle</h1>
        <p>Привет, <b>$User</b>!</p>
        <p>Сервер запущен на порту: <code>$systemInfo.port</code></p>
        <button onclick="alert('AsanaliScript работает идеально!')">Проверить связь</button>
    </div>
)
